<script setup>
import { computed } from 'vue'
import EntityAvatar from './EntityAvatar.vue'
const props=defineProps({ rounds:{type:Array,default:()=>[]},matches:{type:Array,default:()=>[]} })
const columns=computed(()=>props.rounds.map(round=>({round,matches:props.matches.filter(m=>Number(m.round_id)===Number(round.id)).sort((a,b)=>Number(a.match_no)-Number(b.match_no))})))
</script>
<template><div v-if="columns.length" class="bracket-shell"><div class="bracket"><section v-for="column in columns" :key="column.round.id" class="round"><header><span>Vòng {{ column.round.round_order }}</span><h3>{{ column.round.round_name }}</h3></header><div class="round-matches"><article v-for="match in column.matches" :key="match.id" class="match-card" :class="{ upset:match.highlighted_upset }"><div class="team" :class="{ winner:Number(match.winner_club_id)===Number(match.home_club_id) }"><EntityAvatar :src="match.home_logo" :name="match.home_club_name||'Chờ xác định'" :size="28"/><span>{{ match.home_club_name||'Chờ xác định' }}</span><b>{{ match.home_score ?? '-' }}</b></div><div class="team" :class="{ winner:Number(match.winner_club_id)===Number(match.away_club_id) }"><EntityAvatar :src="match.away_logo" :name="match.away_club_name||'Chờ xác định'" :size="28"/><span>{{ match.away_club_name||'Chờ xác định' }}</span><b>{{ match.away_score ?? '-' }}</b></div><small v-if="match.highlighted_upset">🔥 Nhà chinh phục đương kim vô địch</small></article></div></section></div></div><div v-else class="empty">Nhánh đấu chưa được tạo.</div></template>
<style scoped>.bracket-shell{overflow:auto;padding:8px 2px 20px}.bracket{display:flex;gap:32px;min-width:max-content;align-items:stretch}.round{width:260px;display:flex;flex-direction:column}.round header{text-align:center;margin-bottom:15px}.round header span{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.1em}.round header h3{font-size:18px;margin-top:4px}.round-matches{flex:1;display:flex;flex-direction:column;justify-content:space-around;gap:20px}.match-card{position:relative;border:1px solid var(--line);border-radius:14px;background:var(--panel-2);padding:8px;box-shadow:0 12px 35px rgba(0,0,0,.18)}.match-card:after{content:'';position:absolute;right:-33px;top:50%;width:32px;border-top:1px solid var(--line-strong)}.round:last-child .match-card:after{display:none}.team{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px;padding:7px;border-radius:9px;color:var(--muted)}.team span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.team b{font-size:16px}.team.winner{background:rgba(53,221,154,.09);color:var(--text)}.team.winner b{color:var(--green)}.match-card small{display:block;color:var(--yellow);padding:6px 7px 3px;font-size:10px}.match-card.upset{border-color:rgba(255,200,87,.42);box-shadow:0 0 28px rgba(255,200,87,.12)}</style>
